/* STM32CubeU5 HAL ADC test.
 *
 * Unmodified HAL. ADC1 in 12-bit resolution converts channel 5 (PA0, datasheet pin table)
 * by software start, configured as generated by STM32CubeMX (HAL_ADC_Init,
 * HAL_ADCEx_Calibration_Start, HAL_ADC_ConfigChannel). The main loop converts the channel with
 * HAL_ADC_Start, HAL_ADC_PollForConversion and HAL_ADC_GetValue and stores the result; the
 * robot test sets the input voltage and reads the global variables. */

#include "clock_160mhz.h"

ADC_HandleTypeDef hadc1;

volatile uint32_t step;
volatile uint32_t failedStep;
volatile uint32_t conversions;
volatile uint32_t value;

void SysTick_Handler(void)
{
    HAL_IncTick();
}

static void check(HAL_StatusTypeDef status, uint32_t at)
{
    step = at;
    if (status != HAL_OK)
    {
        failedStep = at;
        for (;;)
        {
        }
    }
}

void HAL_ADC_MspInit(ADC_HandleTypeDef *hadc)
{
    RCC_PeriphCLKInitTypeDef clock = {0};
    GPIO_InitTypeDef init = {0};

    if (hadc->Instance != ADC1)
    {
        return;
    }
    clock.PeriphClockSelection = RCC_PERIPHCLK_ADCDAC;
    clock.AdcDacClockSelection = RCC_ADCDACCLKSOURCE_HSI;
    check(HAL_RCCEx_PeriphCLKConfig(&clock), 100);
    __HAL_RCC_ADC12_CLK_ENABLE();
    __HAL_RCC_GPIOA_CLK_ENABLE();

    init.Pin = GPIO_PIN_0;
    init.Mode = GPIO_MODE_ANALOG;
    init.Pull = GPIO_NOPULL;
    HAL_GPIO_Init(GPIOA, &init);
}

int main(void)
{
    check(HAL_Init(), 1);
    check(SystemClockConfig160MHz(), 2);

    hadc1.Instance = ADC1;
    hadc1.Init.ClockPrescaler = ADC_CLOCK_ASYNC_DIV1;
    hadc1.Init.Resolution = ADC_RESOLUTION_12B;
    hadc1.Init.GainCompensation = 0;
    hadc1.Init.ScanConvMode = ADC_SCAN_DISABLE;
    hadc1.Init.EOCSelection = ADC_EOC_SINGLE_CONV;
    hadc1.Init.LowPowerAutoWait = DISABLE;
    hadc1.Init.ContinuousConvMode = DISABLE;
    hadc1.Init.NbrOfConversion = 1;
    hadc1.Init.DiscontinuousConvMode = DISABLE;
    hadc1.Init.ExternalTrigConv = ADC_SOFTWARE_START;
    hadc1.Init.ExternalTrigConvEdge = ADC_EXTERNALTRIGCONVEDGE_NONE;
    hadc1.Init.DMAContinuousRequests = DISABLE;
    hadc1.Init.TriggerFrequencyMode = ADC_TRIGGER_FREQ_HIGH;
    hadc1.Init.Overrun = ADC_OVR_DATA_PRESERVED;
    hadc1.Init.LeftBitShift = ADC_LEFTBITSHIFT_NONE;
    hadc1.Init.ConversionDataManagement = ADC_CONVERSIONDATA_DR;
    hadc1.Init.OversamplingMode = DISABLE;
    check(HAL_ADC_Init(&hadc1), 3);
    check(HAL_ADCEx_Calibration_Start(&hadc1, ADC_CALIB_OFFSET, ADC_SINGLE_ENDED), 4);

    ADC_ChannelConfTypeDef channel = {0};
    channel.Channel = ADC_CHANNEL_5;
    channel.Rank = ADC_REGULAR_RANK_1;
    channel.SamplingTime = ADC_SAMPLETIME_5CYCLE;
    channel.SingleDiff = ADC_SINGLE_ENDED;
    channel.OffsetNumber = ADC_OFFSET_NONE;
    channel.Offset = 0;
    check(HAL_ADC_ConfigChannel(&hadc1, &channel), 5);

    step = 6;
    for (;;)
    {
        check(HAL_ADC_Start(&hadc1), 7);
        check(HAL_ADC_PollForConversion(&hadc1, 10), 8);
        value = HAL_ADC_GetValue(&hadc1);
        conversions++;
        check(HAL_ADC_Stop(&hadc1), 9);
        HAL_Delay(10);
    }
}
